INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 18, 'theory', 'Quiz: CSS Box Model, Styling and Positioning');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 18, 0, 'What is the full width of a block with width: 100px, padding: 20px and a 2px border, if box-sizing was not changed?', '["100px: the width is always the full one", "140px", "144px", "104px"]', 2, 'By default width sets only the content, and padding and border on both sides are added to it: 100 + 2×20 + 2×2 = 144px. With box-sizing: border-box the full width would stay at 100px.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 18, 1, 'Between two paragraphs: the first has margin-bottom 20px, the second margin-top 30px. What will the gap between them be?', '["30px: vertical margins collapse, the larger one wins", "50px: the margins add up", "20px: the first one wins", "0: the margins cancel each other out"]', 0, 'Vertical margins of adjacent blocks collapse to the larger value. Horizontal ones never collapse, and a parent avoids the effect with padding, a border, flow-root or a flex container.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 18, 2, 'Why can''t you just remove the focus outline with outline: none?', '["It would break the layout: the outline takes up space", "The browser needs the outline to draw the border", "The outline property is forbidden by the standard", "A person using a keyboard would no longer see where the focus is"]', 3, 'The outline is the only visible sign of focus for those who move around the page with the Tab key. You can replace it with your own (for example on :focus-visible), but not leave the element with no indication. The outline does not affect the layout.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 18, 3, 'A badge must be pinned to the top right corner of a card. What is needed for that?', '["position: fixed on the badge", "position: relative on the card and position: absolute with top and right on the badge", "position: sticky on the card", "float: right on the badge"]', 1, 'An absolutely positioned element is measured from the nearest ancestor whose position is not static. So the card gets relative to become the reference point, and the badge gets absolute and offsets. Without relative, the badge would fly off to the edge of the page.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 18, 4, 'A child element has z-index: 999, but still ends up under a neighboring block with z-index: 2. What could have happened?', '["The browser ignores z-index above 100", "You need to write !important", "The parent forms a stacking context with z-index: 1, so the parent is compared with the neighbor, not the descendant", "The neighbor has a lighter background color"]', 2, 'A parent with a position and z-index (or with opacity below one, or a transform) creates a closed stacking context: its descendants are compared with each other inside it, while from outside the whole parent takes part. That is why it is better to keep a small scale of layers.');
